fn get_column(input: &Vec<Vec<i8>>, j: usize, _m: usize, n: usize) -> Vec<i8> {
    // Extract the j-th column from the input matrix
    // Input matrix has n rows, each with m columns.
    // We'll collect input[i][j] for i in 0..n.
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Build the transposed matrix by stacking columns as rows
    // Output will have m rows, each containing n elements
    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        let col = get_column(&input, j, m, n);
        result.push(col);
    }
    result
}